#include <bits/stdc++.h>
using namespace std;

static long long isqrt(long long x) {
    long long r = (long long)sqrtl((long double)x);
    while (r * r > x) r--;
    while ((r + 1) * (r + 1) <= x) r++;
    return r;
}

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    vector<long long> xs(q);
    long long mx = 1;
    for (auto &x : xs) {
        scanf("%lld", &x);
        mx = max(mx, x);
    }
    // Numbers with exactly 3 divisors are p^2: count primes up to isqrt(x).
    int lim = (int)isqrt(mx);
    vector<char> composite(lim + 1, 0);
    vector<int> primes;
    for (int p = 2; p <= lim; p++) {
        if (composite[p]) continue;
        primes.push_back(p);
        for (long long m = (long long)p * p; m <= lim; m += p) composite[m] = 1;
    }
    string out;
    for (int i = 0; i < q; i++) {
        long long r = isqrt(xs[i]);
        if (i) out += '\n';
        out += to_string(upper_bound(primes.begin(), primes.end(), r) - primes.begin());
    }
    out += '\n';
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static long isqrt(long x) {
        long r = (long) Math.sqrt((double) x);
        while (r * r > x) r--;
        while ((r + 1) * (r + 1) <= x) r++;
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int q = nextInt();
        long[] xs = new long[q];
        long mx = 1;
        for (int i = 0; i < q; i++) {
            xs[i] = nextLong();
            mx = Math.max(mx, xs[i]);
        }
        // Numbers with exactly 3 divisors are p^2: count primes up to isqrt(x).
        int lim = (int) isqrt(mx);
        boolean[] composite = new boolean[lim + 1];
        int[] primes = new int[lim + 1];
        int cnt = 0;
        for (int p = 2; p <= lim; p++) {
            if (composite[p]) continue;
            primes[cnt++] = p;
            for (long m = (long) p * p; m <= lim; m += p) composite[(int) m] = true;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long r = isqrt(xs[i]);
            // Upper bound: number of primes <= r.
            int lo = 0, hi = cnt;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (primes[mid] <= r) lo = mid + 1;
                else hi = mid;
            }
            if (i > 0) sb.append('\n');
            sb.append(lo);
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"math"
	"sort"
	"strconv"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func isqrt(x int64) int64 {
	r := int64(math.Sqrt(float64(x)))
	for r*r > x {
		r--
	}
	for (r+1)*(r+1) <= x {
		r++
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := int(nextInt())
	xs := make([]int64, q)
	mx := int64(1)
	for i := range xs {
		xs[i] = nextInt()
		mx = max(mx, xs[i])
	}
	// Numbers with exactly 3 divisors are p^2: count primes up to isqrt(x).
	lim := int(isqrt(mx))
	composite := make([]bool, lim+1)
	primes := []int64{}
	for p := 2; p <= lim; p++ {
		if composite[p] {
			continue
		}
		primes = append(primes, int64(p))
		for m := p * p; m <= lim; m += p {
			composite[m] = true
		}
	}
	out := make([]byte, 0, 8*q)
	for i, x := range xs {
		r := isqrt(x)
		cnt := sort.Search(len(primes), func(j int) bool { return primes[j] > r })
		if i > 0 {
			out = append(out, '\n')
		}
		out = strconv.AppendInt(out, int64(cnt), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
